// Multiple-choice questions and flashcards for IPE 331 (Prianka ma'am's slides).
// Chapter ids: intro, turning, milling, shaping, grinding, drilling.

const counters = {};
// mc(chapter, question, correct, [wrong1, wrong2, wrong3], why, slide) -> correct option placed at a rotating position
function mc(chapter, q, correct, wrong, why, slide) {
  counters[chapter] = (counters[chapter] || 0) + 1;
  const n = (counters.__all = (counters.__all || 0) + 1);
  const pos = (n * 3 + 1) % 4;
  const options = wrong.slice();
  options.splice(pos, 0, correct);
  return { id: `${chapter}-mcq-${String(counters[chapter]).padStart(2, '0')}`, chapter, q, options, answer: pos, why, slide };
}

